import Image from 'next/image'
import { BRAND } from '@/constants'
import { cn } from '@/lib/cn'

interface Props {
  title?: string
  admission?: string
  date?: string
  time?: string
  width?: number
  /** Colour behind the card, the notches are cut-outs filled with it */
  backdrop?: string
  className?: string
}

// Gorave ticket: real scannable QR (public/img/ticket-qr.svg, generated by
// scripts/generate-ticket-qr.mjs) with the logo knocked out of the centre,
// notched ticket edges and a perforation line.
export function TicketCard({
  title = 'Sunset Rooftop Sessions',
  admission = 'General Admission',
  date = 'Saturday, 18 October',
  time = '6:00 PM IST',
  width = 260,
  backdrop = 'var(--color-cream)',
  className,
}: Props) {
  const s = width / 260 // everything scales from a 260px design
  const notch = 14 * s

  return (
    <div
      className={cn('relative overflow-hidden text-white shadow-pop', className)}
      style={{
        width,
        borderRadius: 22 * s,
        padding: 16 * s,
        background:
          'radial-gradient(120% 70% at 100% 0%, rgb(255 56 100 / 0.55), transparent 60%),' +
          'radial-gradient(90% 60% at 0% 100%, rgb(255 107 53 / 0.45), transparent 60%),' +
          'linear-gradient(160deg, #2b1612 0%, #3a1a14 45%, #1b1110 100%)',
      }}
    >
      {/* top/bottom centre notches */}
      <span className="absolute left-1/2 -translate-x-1/2 rounded-full" style={{ top: -notch / 2, width: notch * 1.6, height: notch, background: backdrop }} />
      <span className="absolute left-1/2 -translate-x-1/2 rounded-full" style={{ bottom: -notch / 2, width: notch * 1.6, height: notch, background: backdrop }} />

      <div className="relative rounded-[14px] bg-[#F7F3EC]" style={{ padding: 14 * s, borderRadius: 14 * s }}>
        <Image src="/img/ticket-qr.svg" alt="Ticket QR code" width={228} height={228} unoptimized className="block h-auto w-full" />
        <div
          className="absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-[10px] bg-[#F7F3EC]"
          style={{ width: 54 * s, height: 54 * s, borderRadius: 12 * s }}
        >
          <Image src={BRAND.logoDark} alt="" width={36} height={36} style={{ width: 34 * s, height: 34 * s }} />
        </div>
      </div>

      {/* perforation with side notches */}
      <div className="relative" style={{ margin: `${16 * s}px ${-16 * s}px` }}>
        <span className="absolute top-1/2 -translate-y-1/2 rounded-full" style={{ left: -notch / 2, width: notch, height: notch, background: backdrop }} />
        <span className="absolute top-1/2 -translate-y-1/2 rounded-full" style={{ right: -notch / 2, width: notch, height: notch, background: backdrop }} />
        <div className="border-t border-dashed border-white/25" style={{ margin: `0 ${notch}px` }} />
      </div>

      <div className="font-sans" style={{ fontSize: 13 * s }}>
        <div className="font-display font-bold leading-tight" style={{ fontSize: 17 * s }}>{title}</div>
        <div className="text-white/60" style={{ fontSize: 15 * s }}>{admission}</div>
        <div className="mt-3 text-white/50" style={{ marginTop: 12 * s, fontSize: 11 * s }}>DATE</div>
        <div className="font-bold">{date}</div>
        <div className="flex items-end justify-between" style={{ marginTop: 8 * s }}>
          <div>
            <div className="text-white/50" style={{ fontSize: 11 * s }}>TIME</div>
            <div className="font-bold">{time}</div>
          </div>
          <Image src={BRAND.logoLight} alt="" width={22} height={22} className="opacity-70" style={{ width: 20 * s, height: 20 * s }} />
        </div>
      </div>
    </div>
  )
}
